<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AuthShell from'../../Components/AuthShell.vue';import PasswordField from'../../Components/PasswordField.vue';import UiButton from'../../Components/UiButton.vue';const props=defineProps({token:String,email:String});const form=useForm({token:props.token,email:props.email,password:'',password_confirmation:''})</script>
<template><Head title="Reset password"/><AuthShell eyebrow="Secure reset" title="Choose a new password" description="Use at least 12 characters with uppercase, lowercase, number and symbol."><form class="space-y-5" @submit.prevent="form.post('/reset-password')"><label class="lp-label">Email address<input v-model="form.email" type="email" autocomplete="email" class="field mt-2" required><span v-if="form.errors.email" class="lp-error">{{form.errors.email}}</span></label><PasswordField v-model="form.password" label="New password" autocomplete="new-password" :error="form.errors.password"/><PasswordField v-model="form.password_confirmation" label="Confirm new password" autocomplete="new-password"/><UiButton type="submit" class="w-full" :loading="form.processing">Reset password</UiButton><p class="text-center text-sm"><Link href="/login" class="font-semibold text-indigo hover:underline">Return to sign in</Link></p></form></AuthShell></template>
